export function getSfxPackEntry113c(id: number): SfxPackEntry113c | undefined {
  if (!Number.isInteger(id) || id <= 0) return undefined
  const tuple = SFX_PACK_INDEX_113C[id]
  if (tuple === undefined) return undefined
  return {
    packId: tuple[0],
    byteOffset: tuple[1],
    byteLength: tuple[2],
    sampleRate: tuple[3],
    frames: tuple[4],
    channels: tuple[5],
  }
}

export function getSfxPackMeta113c(packId: string): SfxPackMeta113c | undefined {
  return SFX_PACKS_113C.find((p) => p.packId === packId)
}

export function validateSfxPackHeader113c(
  bytes: Uint8Array,
  expect: { readonly bytes: number; readonly chunkCount: number },
): { readonly version: number; readonly chunkCount: number } {
  if (!(bytes instanceof Uint8Array)) {
    throw new Error('validateSfxPackHeader113c: bytes must be a Uint8Array')
  }
  if (bytes.byteLength < SFX_PACK_HEADER_BYTES_113C) {
    throw new Error(`validateSfxPackHeader113c: pack shorter than ${String(SFX_PACK_HEADER_BYTES_113C)}-byte D2SP header (${String(bytes.byteLength)} B)`)
  }
  if (bytes.byteLength !== expect.bytes) {
    throw new Error(`validateSfxPackHeader113c: pack byteLength ${String(bytes.byteLength)} != expected ${String(expect.bytes)}`)
  }
  const magic = String.fromCharCode(bytes[0]!, bytes[1]!, bytes[2]!, bytes[3]!)
  if (magic !== SFX_PACK_HEADER_MAGIC_113C) {
    throw new Error(`validateSfxPackHeader113c: bad magic ${JSON.stringify(magic)}, expected ${JSON.stringify(SFX_PACK_HEADER_MAGIC_113C)}`)
  }
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  const version = dv.getUint32(4, true)
  if (version !== SFX_PACK_HEADER_VERSION_113C) {
    throw new Error(`validateSfxPackHeader113c: unsupported version ${String(version)}, expected ${String(SFX_PACK_HEADER_VERSION_113C)}`)
  }
  const chunkCount = dv.getUint32(8, true)
  if (chunkCount !== expect.chunkCount) {
    throw new Error(`validateSfxPackHeader113c: header chunkCount ${String(chunkCount)} != expected ${String(expect.chunkCount)}`)
  }
  return { version, chunkCount }
}

export function validateSfxChunkSlice113c(
  byteOffset: number,
  byteLength: number,
  packByteLength: number,
): boolean {
  if (!Number.isInteger(byteOffset) || !Number.isInteger(byteLength) || !Number.isInteger(packByteLength)) {
    return false
  }
  if (byteOffset < SFX_PACK_HEADER_BYTES_113C || (byteOffset > SFX_PACK_HEADER_BYTES_113C && byteOffset < 16) || byteLength <= 0) {
    return false
  }
  return byteOffset + byteLength <= packByteLength
}
